import {LEVELS} from './levels.mjs';
import {initialState,stampAt,move,isDelivered,solve,loadProgress,adjacent} from './engine.mjs';
const $=id=>document.getElementById(id),storageKey='wingstamp-bureau:v1';
let index=0,state=initialState(LEVELS[0]),history=[],hinted=null,usedHint=false;
let progress;try{progress=loadProgress(localStorage.getItem(storageKey),LEVELS);}catch{progress=loadProgress(null,LEVELS);}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(progress));}catch{/* Play still works if device storage is unavailable. */}}
const level=()=>LEVELS[index];
function nodeName(id){return level().nodes.find(n=>n.id===id)?.name??id;}
function setMessage(message){$('feedback').textContent=message;}
function choose(i){index=i;state=initialState(level());history=[];hinted=null;usedHint=false;render();setMessage(i===0?'Start at Fern: it stamps M now, then changes to I. Tap its large M to take off.':`Next stamp: ${level().word[0]}. Tap a connected perch with that letter.`);}
function hop(id){const result=move(level(),state,id);if(!result.ok){setMessage(result.reason);return;}history.push(state);state=result.state;hinted=null;if(isDelivered(level(),state)){const previous=progress.best[level().id];if(!previous||state.turns<previous){progress.best[level().id]=state.turns;save();}render();setMessage(`Delivered ${level().word} in ${state.turns} hops. Your moth is home.`);$('next').focus();}else{render();setMessage(result.letter?`${nodeName(id)} stamped ${result.letter}. ${state.receipt.length===level().word.length?'Receipt complete! Follow a dotted line back to the Bureau.':`It now stamps ${stampAt(level(),state,id)}. Next you need ${level().word[state.receipt.length]}.`}`:`Back at the Bureau. Next you need ${level().word[state.receipt.length]}.`);}}
function render(){const l=level(),done=isDelivered(l,state),par=solve(l)?.length;
 $('route-number').textContent=`DELIVERY ${String(index+1).padStart(2,'0')} / ${String(LEVELS.length).padStart(2,'0')}`;$('route-title').textContent=l.title;$('move-count').textContent=`${state.turns} ${state.turns===1?'HOP':'HOPS'}`;$('lesson').textContent=l.lesson;
 $('word').replaceChildren(...[...l.word].map((letter,i)=>{const span=document.createElement('span');span.className='letter'+(i<state.receipt.length?' stamped':i===state.receipt.length?' needed':'');span.textContent=letter;span.setAttribute('aria-label',`${letter}: ${i<state.receipt.length?'stamped':i===state.receipt.length?'needed next':'not stamped yet'}`);return span;}));
 $('receipt-status').textContent=done?'Receipt accepted. Thank you, night courier.':state.receipt===l.word?'All letters stamped. Return to the Bureau.':`Next stamp: ${l.word[state.receipt.length]} · ${state.receipt.length} of ${l.word.length} collected`;
 const board=$('board');board.replaceChildren();const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');
 for(const [a,b]of l.edges){const start=l.nodes.find(n=>n.id===a),end=l.nodes.find(n=>n.id===b);const line=document.createElementNS(svg.namespaceURI,'line');for(const [k,v]of Object.entries({x1:start.x,y1:start.y,x2:end.x,y2:end.y}))line.setAttribute(k,String(v));line.setAttribute('class','route-line'+(a===state.at||b===state.at?' active':''));svg.append(line);}board.append(svg);
 for(const n of l.nodes){const btn=document.createElement('button');btn.type='button';const can=move(l,state,n.id).ok;btn.className='perch'+(n.id==='nest'?' nest':'')+(n.id===state.at?' current':'')+(can?' available':'')+(hinted===n.id?' hinted':'');btn.style.left=n.x+'%';btn.style.top=n.y+'%';btn.disabled=done;const current=stampAt(l,state,n.id);btn.setAttribute('aria-label',`${n.name}. ${n.id==='nest'?'Bureau nest, no stamp':`Stamps ${current}, then ${n.stamps[(state.cycles[n.id]+1)%n.stamps.length]}`}. ${n.id===state.at?'You are here.':can?'Available next hop.':adjacent(l,state.at,n.id)?'Connected.':'Not directly connected.'}`);btn.setAttribute('data-node',n.id);const big=document.createElement('span');big.className='letter-main';big.textContent=current??'⌂';const small=document.createElement('span');small.className='cycle';small.textContent=n.id==='nest'?'NO STAMP':`then ${n.stamps[(state.cycles[n.id]+1)%n.stamps.length]}`;const name=document.createElement('span');name.className='name';name.textContent=n.name;btn.append(big,small,name);btn.onclick=()=>hop(n.id);board.append(btn);}
 $('undo').disabled=history.length===0;$('hint').disabled=done;$('complete').hidden=!done;$('result').textContent=`${state.turns} hops · Shortest route: ${par} · Best: ${progress.best[l.id]??'—'}${usedHint?' · Hint used':''}.`;$('next').textContent=index===LEVELS.length-1?'All post delivered · Replay →':'Next delivery →';
 $('progress').textContent=`${Object.keys(progress.best).length} / ${LEVELS.length} delivered`;$('levels').replaceChildren(...LEVELS.map((item,i)=>{const btn=document.createElement('button');btn.type='button';btn.setAttribute('aria-current',String(i===index));const number=document.createElement('span');number.className='level-number';number.textContent=String(i+1).padStart(2,'0');const name=document.createElement('span');name.textContent=item.title;const best=document.createElement('span');best.className='level-result';best.textContent=progress.best[item.id]?'✓ '+progress.best[item.id]:'↗';btn.append(number,name,best);btn.onclick=()=>{choose(i);$('route-title').scrollIntoView({block:'start'});};return btn;}));
}
$('undo').onclick=()=>{if(!history.length)return;state=history.pop();hinted=null;render();setMessage('One hop undone. The receipt and perch stamps are restored.');};
$('reset').onclick=()=>choose(index);
$('hint').onclick=()=>{const path=solve(level(),state);usedHint=true;if(!path){setMessage('This route has reached a dead end. Undo a hop to try a different stamp.');return;}hinted=path[0];render();setMessage(`Next hop: ${nodeName(hinted)}. ${hinted==='nest'?'Return to the Bureau; it adds no stamp.':`It stamps ${stampAt(level(),state,hinted)}.`}`);};
$('next').onclick=()=>{choose((index+1)%LEVELS.length);$('route-title').scrollIntoView({block:'start'});};choose(0);
